// ---------- Helpers ----------

function row(label, value) {
  return `<div class="row"><div class="label">${escapeHtml(label)}</div><div class="colon">:</div><div class="value">${escapeHtml(value) || ''}</div></div>`;
}

function escapeHtml(str) {
  if (str === undefined || str === null) return '';
  return String(str)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function nl2html(str) {
  return escapeHtml(str).replaceAll('\n', '<br>');
}

// ---------- Kop surat (letterhead) shared helpers ----------

const LOGO_DATA_URI = 'data:image/png;base64,';

// Fields every institutional letter starts with (editable — defaults to the
// user's institution but can be changed for any other instansi).
const letterheadFields = [
  { id: 'instansiNama', label: 'Nama Instansi/Lembaga', type: 'text', placeholder: "DENNY'S BUNCH" },
  { id: 'instansiSub', label: 'Sub-judul Instansi (opsional)', type: 'text', placeholder: 'LEMBAGA PENDIDIKAN NONFORMAL (PNF)' },
  { id: 'instansiAlamat', label: 'Alamat Instansi', type: 'text', placeholder: 'Jl. D.I Panjaitan no.95 Lumajang, Jawa Timur 67312' },
  { id: 'instansiKontak', label: 'Telp / Email / Website', type: 'text', placeholder: 'Telp: (0334)886145 — dennysbunchcourse@gmail.com' },
  { id: 'nomor', label: 'Nomor Surat', type: 'text', placeholder: '001/001-DB/IX/2026' },
  { id: 'hal', label: 'Hal / Perihal', type: 'text', placeholder: 'Undangan Rapat Wali Siswa' },
  { id: 'kepadaYth', label: 'Ditujukan Kepada', type: 'text', placeholder: 'Bapak/Ibu Wali Siswa' },
];

const letterheadDefaults = {
  instansiNama: "DENNY'S BUNCH",
  instansiSub: 'LEMBAGA PENDIDIKAN NONFORMAL (PNF)',
  instansiAlamat: 'Jl. D.I Panjaitan no.95 Lumajang, Jawa Timur, kode pos: 67312',
  instansiKontak: "Telp: (0334)886145 / 085546800085 (WA) — dennysbunchcourse@gmail.com — www.denny's-bunch.com",
};

function withLetterhead(extraFields) {
  return [...letterheadFields, ...extraFields];
}

function letterheadHtml(d) {
  return `
    <div class="letterhead">
      <img src="${LOGO_DATA_URI}" alt="Logo">
      <div class="lh-text">
        ${d.instansiSub ? `<p class="lh-org">${escapeHtml(d.instansiSub)}</p>` : ''}
        <p class="lh-name">${escapeHtml(d.instansiNama) || '.....'}</p>
        ${d.instansiAlamat ? `<p class="lh-sub">${escapeHtml(d.instansiAlamat)}</p>` : ''}
        ${d.instansiKontak ? `<p class="lh-sub">${escapeHtml(d.instansiKontak)}</p>` : ''}
      </div>
    </div>
  `;
}

function docMetaHtml(d) {
  return `
    <div class="doc-meta">
      <div class="meta-left">
        ${row('Nomor', d.nomor)}
        ${row('Hal', d.hal)}
      </div>
      <div class="meta-right">
        <div>Kepada Yth.</div>
        <div><strong>${escapeHtml(d.kepadaYth) || '.....'}</strong></div>
        <div>di Tempat</div>
      </div>
    </div>
  `;
}

