// Pre-filled example so the preview is never blank.
// Institutional letter types (anything with kop surat) inherit letterheadDefaults
// automatically; only per-type specifics are listed here.
const sampleData = {
  izin: {
    status: 'Orang Tua', namaOrtu: 'Senishatun', alamatOrtu: 'Dusun Krajan II Desa Grenden Puger',
    pekerjaanOrtu: 'Mengurus Rumah Tangga', namaAnak: 'Muhamad Ali Makfur', ttlAnak: 'Jember, 07 Juli 2002',
    jkAnak: 'Laki-Laki', alamatAnak: 'Dusun Krajan II Desa Grenden Puger',
    alamatTinggal: 'Dusun Krajan Desa Sumberanyar Rowokangkung',
    keperluan: 'bekerja di Perusahaan yang Bapak/Ibu pimpin', tempatSurat: 'Jember', tanggalSurat: ''
  }
};

// Types that carry a kop surat (letterhead) — everything except the personal
// letters (permohonan, pernyataan, izin) get the institution defaults merged in.
const personalTypes = ['permohonan', 'pernyataan', 'izin'];

// ---------- Date formatting ----------

const bulanID = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];

function fmtDate(isoStr) {
  if (!isoStr) return '.....';
  const [y, m, d] = isoStr.split('-');
  if (!y || !m || !d) return '.....';
  return `${parseInt(d, 10)} ${bulanID[parseInt(m, 10) - 1]} ${y}`;
}

// ---------- App state & rendering ----------

let currentType = 'tugas';

function buildTabs() {
  const tabsEl = document.getElementById('tabs');
  tabsEl.innerHTML = '';
  Object.keys(letterTypes).forEach(key => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'tab-btn' + (key === currentType ? ' active' : '');
    btn.textContent = letterTypes[key].title;
    btn.addEventListener('click', () => switchType(key));
    tabsEl.appendChild(btn);
  });
}

function switchType(key) {
  currentType = key;
  buildTabs();
  buildForm();
  renderPaper();
}

function buildForm() {
  const type = letterTypes[currentType];
  document.getElementById('formTitle').textContent = type.title;
  const form = document.getElementById('letterForm');
  form.innerHTML = '';
  const defaults = personalTypes.includes(currentType)
    ? (sampleData[currentType] || {})
    : { ...letterheadDefaults, ...(sampleData[currentType] || {}) };

  type.fields.forEach(f => {
    const wrap = document.createElement('div');
    wrap.className = 'field';

    const label = document.createElement('label');
    label.setAttribute('for', f.id);
    label.textContent = f.label;
    wrap.appendChild(label);

    let input;
    if (f.type === 'textarea') {
      input = document.createElement('textarea');
    } else if (f.type === 'select') {
      input = document.createElement('select');
      f.options.forEach(opt => {
        const o = document.createElement('option');
        o.value = opt;
        o.textContent = opt;
        input.appendChild(o);
      });
    } else {
      input = document.createElement('input');
      input.type = f.type;
      if (f.placeholder) input.placeholder = f.placeholder;
    }
    input.id = f.id;
    input.name = f.id;
    if (defaults[f.id] !== undefined) input.value = defaults[f.id];
    input.addEventListener('input', renderPaper);
    input.addEventListener('change', renderPaper);

    wrap.appendChild(input);
    form.appendChild(wrap);
  });
}

function collectFormData() {
  const type = letterTypes[currentType];
  const data = {};
  type.fields.forEach(f => {
    const el = document.getElementById(f.id);
    data[f.id] = el ? el.value : '';
  });
  return data;
}

function renderPaper() {
  const data = collectFormData();
  const paper = document.getElementById('paper');
  paper.innerHTML = letterTypes[currentType].render(data);
}

document.getElementById('printBtn').addEventListener('click', () => window.print());

buildTabs();
buildForm();
renderPaper();
